@@ -0,0 +1,32 @@
+// Sites (kitchens). Every location belongs to one site, and stock belongs to
+// the site of the location it is in. Items, suppliers, recipes and dishes are
+// shared by all sites. Functions that take an optional `site` look at every
+// site when it is left out (tools, exports, the nightly job).
+import { AppError } from "../errors.js";
+
+/** The site of requests that do not name one, and of data from before sites. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in the order they were added. */
+export function listSites(store) {
+  return [...store.data.sites];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and belongs to `site` (any site when undefined). */
+export function locationInSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && (site === undefined || l.site === site));
+}
+
+/** A filter for batches stored at `site` (every batch when undefined). */
+export function batchesAt(store, site) {
+  if (site === undefined) return () => true;
+  const ids = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  return (batch) => ids.has(batch.location);
+}
