+++ b/tests/sites.test.js
@@ -0,0 +1,104 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+// Puts 3 kg of onion (item 1) in the annex fridge by receiving an order there.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", headers: annex, body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send`, headers: annex });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: annex, body: { lots: [{ lot: "AX-1", expires: "2026-10-29", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("the seed has two sites and every location belongs to one", async () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  assert.ok(store.data.locations.every((l) => store.data.sites.some((s) => s.id === l.site)));
+  assert.deepEqual(store.data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex", kind: "fridge" });
+});
+
+test("an unknown site is a 400 with its own code; no header means main", async () => {
+  const { handle } = app();
+  const bad = await handle({ path: "/items", headers: { "x-larder-site": "cellar" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /cellar/);
+  const plain = await handle({ path: "/batches" });
+  const main = await handle({ path: "/batches", headers: { "x-larder-site": "main" } });
+  assert.deepEqual(plain.body, main.body);
+  assert.equal(plain.body.length, 9);
+});
+
+test("batches and stock on hand are per site; items are shared", async () => {
+  const { handle } = app();
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  const batch = await stockAnnex(handle);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [batch.id]);
+  assert.equal((await handle({ path: "/batches" })).body.length, 9);
+  assert.equal((await handle({ path: "/items/1", headers: annex })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/1" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/items", headers: annex })).body.length, 6);
+  assert.equal((await handle({ path: `/batches/${batch.id}` })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/batches/${batch.id}/waste`, body: { qty: 1 } })).body.error.code, "unknown_batch");
+});
+
+test("receiving needs a location of the request's site", async () => {
+  const { handle } = app();
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 3 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, body: { lots: [{ lot: "X", expires: null, location: "annex-fridge" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+  assert.equal((await handle({ path: `/orders/${order.id}` })).body.state, "sent");
+});
+
+test("cooking only uses the request's site", async () => {
+  const { handle, store } = app();
+  await stockAnnex(handle);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+  const ok = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 4 } });
+  assert.equal(ok.status, 200);
+  const main = new Set(store.data.locations.filter((l) => l.site === "main").map((l) => l.id));
+  const byId = new Map(store.data.batches.map((b) => [b.id, b]));
+  assert.ok(ok.body.used.flatMap((u) => u.batches).every((u) => main.has(byId.get(u.batchId).location)));
+  assert.equal((await handle({ path: "/items/1", headers: annex })).body.onHand, 3);
+});
+
+test("alerts and stock value are per site", async () => {
+  const { handle } = app();
+  const mainValue = (await handle({ path: "/reports/stock-value" })).body.totalCents;
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  const batch = await stockAnnex(handle);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 540);
+  assert.equal((await handle({ path: "/reports/stock-value" })).body.totalCents, mainValue);
+  const a = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(a.expiring.map((b) => b.id), [batch.id]);
+  assert.equal(a.lowStock.length, 6);
+  const m = (await handle({ path: "/alerts" })).body;
+  assert.ok(m.expiring.every((b) => b.id !== batch.id));
+});
+
+test("stock-takes belong to the site of their location", async () => {
+  const { handle } = app();
+  const batch = await stockAnnex(handle);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).body.error.code, "unknown_location");
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "dry" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: batch.id, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: annex, body: { batchId: batch.id, counted: 2 } });
+  const done = await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex });
+  assert.deepEqual(done.body.lines, [{ batchId: batch.id, expected: 3, counted: 2, diff: -1 }]);
+});
+
+test("the annex fridge is held to the fridge limit", async () => {
+  const { handle } = app();
+  const warm = await handle({ method: "POST", path: "/temperatures", headers: annex, body: { location: "annex-fridge", celsius: 7 } });
+  assert.equal(warm.body.ok, false);
+});
